VOWELS = "aeiou"


def _translate_word(word):
    if word[0] in VOWELS or word.startswith(("xr", "yt")):
        return word + "ay"

    # Find where the leading consonant cluster ends.
    # 'y' counts as a vowel once it is not the first letter.
    i = 0
    while i < len(word) and word[i] not in VOWELS and not (i > 0 and word[i] == "y"):
        i += 1

    # If the cluster is followed by "qu", move the "qu" along with it.
    if i < len(word) and word[i] == "q" and i + 1 < len(word) and word[i + 1] == "u":
        i += 2

    return word[i:] + word[:i] + "ay"


def translate(text):
    return " ".join(_translate_word(word) for word in text.split())

